    if (!resultMap.containsKey("set1") || !resultMap.containsKey("set2")) {
        throw new IllegalArgumentException("Result map must contain 'set1' and 'set2' keys");
    }

    Set<V> set1 = (Set<V>) resultMap.get("set1");
    Set<V> set2 = (Set<V>) resultMap.get("set2");

    // Add all vertices from both sets to the graph
    for (V vertex : set1) {
        target.addVertex(vertex);
    }
    for (V vertex : set2) {
        target.addVertex(vertex);
    }

    // Connect each vertex in set1 to each vertex in set2
    for (V vertex1 : set1) {
        for (V vertex2 : set2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

