    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and result map cannot be null.");
    }
    if (resultMap.size() < 2) {
        throw new IllegalArgumentException("Result map must contain at least two vertices to form a bipartite graph.");
    }

    // Split the resultMap values into two sets to represent the bipartition
    List<V> vertices = new ArrayList<>(resultMap.values());
    int size = vertices.size();
    int mid = size / 2;

    Set<V> set1 = new HashSet<>(vertices.subList(0, mid));
    Set<V> set2 = new HashSet<>(vertices.subList(mid, size));

    // Add edges between all vertices in set1 and set2
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
