    out.write(delimBuffer, 0, delimSize);
    out.write(buffer.buffer, 0, messageSize);
    LinkedBuffer tempBuffer = buffer.next;
    while (tempBuffer != null) {
        out.write(tempBuffer.buffer, 0, tempBuffer.offset);
        LinkedBuffer lastBuffer = tempBuffer;
        tempBuffer = tempBuffer.next;
        lastBuffer.clear();
    }
    return delimSize + messageSize;
}

private static int computeRawVarint32Size(final int value) {
    if ((value & (0xffffffff <<  7)) == 0) return 1;
    if ((value & (0xffffffff << 14)) == 0) return 2;
    if ((value & (0xffffffff << 21)) == 0) return 3;
    if ((value & (0xffffffff << 28)) == 0) return 4;
    return 5;
}

