            }
        } else {
            size += 3;
        }
    }
    byte[] buffer = lb.buffer;
    int offset = lb.start;
    int remaining = buffer.length - offset;

    if (remaining < size) {
        lb = lb.next = new LinkedBuffer(session, Math.max(session.startBufferSize, size));
        buffer = lb.buffer;
        offset = lb.start;
    }

    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            buffer[offset++] = (byte) c;
        } else if (c < 0x800) {
            buffer[offset++] = (byte) (0xc0 | (c >> 6));
            buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        } else if (Character.isSurrogate(c)) {
            if (i + 1 < len && Character.isSurrogatePair(c, str.charAt(i + 1))) {
                int cp = Character.toCodePoint(c, str.charAt(++i));
                buffer[offset++] = (byte) (0xf0 | (cp >> 18));
                buffer[offset++] = (byte) (0x80 | ((cp >> 12) & 0x3f));
                buffer[offset++] = (byte) (0x80 | ((cp >> 6) & 0x3f));
                buffer[offset++] = (byte) (0x80 | (cp & 0x3f));
            } else {
                throw new IllegalArgumentException("Invalid UTF-16 sequence");
            }
        } else {
            buffer[offset++] = (byte) (0xe0 | (c >> 12));
            buffer[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
            buffer[offset++] = (byte) (0x80 | (c & 0x3f));
        }
        remaining -= (offset - lb.start);
        lb.start = offset;
        if (remaining == 0 && i + 1 < len) {
            lb = lb.next = new LinkedBuffer(session, session.startBufferSize);
            buffer = lb.buffer;
            offset = lb.start;
            remaining = buffer.length - offset;
        }
    }
    lb.start = offset;
    return lb;
}

