public long readRawVarint64() throws IOException {
    long value = 0;
    int shift = 0;
    int b;
    do {
        b = read(); // Assuming a read() method that reads a single byte
        if (b == -1) {
            throw new EOFException("Reached the end of the input stream while reading Varint");
        }
        value |= (b & 0x7F) << shift;
        shift += 7;
    } while ((b & 0x80) != 0);
    if (shift >= 64) {
        throw new IOException("Varint is too large to fit in a 64-bit long");
    }
    return value;
}

