Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    if (box == null) {
        throw new IllegalArgumentException("The box cannot be null.");
    }
    double midX = box.getMinX() + box.getWidth() / 2.0;
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), midX - box.getMinX(), box.getHeight());
    Box2D rightBox = new Box2D(midX, box.getMinY(), box.getMaxX() - midX, box.getHeight());
    return new Pair<>(leftBox, rightBox);
}

Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }
    double width = box.getWidth();
    if (width <= 0) {
        throw new IllegalArgumentException("Box width must be greater than zero");
    }
    double halfWidth = width / 2.0;
    Box2D leftBox = new Box2D(box.getX(), box.getY(), halfWidth, box.getHeight());
    Box2D rightBox = new Box2D(box.getX() + halfWidth, box.getY(), halfWidth, box.getHeight());
    return new Pair<>(leftBox, rightBox);
