@Override protected Object convertToType(final Class<?> type,final Object value) throws Exception {
    if (type != Character.class && type != Character.TYPE) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String strValue = (String) value;
        if (strValue.length() != 1) {
            throw new IllegalArgumentException("String value must be of length 1 to convert to Character");
        }
        return strValue.charAt(0);
    }
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        if (intValue < Character.MIN_VALUE || intValue > Character.MAX_VALUE) {
            throw new IllegalArgumentException("Number value out of Character range");
        }
        return (char) intValue;
    }
    throw new IllegalArgumentException("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

