    while ((read = read()) != -1) {
        if (read == 0) { // Assuming 0 is the delimiter for the end of the string
            break;
        }
        buff.append((char) read);
    }
    return buff.toString();
}

@Override public String readString() throws IOException {
    int length = readInt(); // Assuming there's a method to read an integer first which denotes the length of the string
    if (length < 0) {
        throw new IOException("Invalid string length: " + length);
    }
    byte[] buffer = new byte[length];
    int bytesRead = 0;
    while (bytesRead < length) {
        int read = read(buffer, bytesRead, length - bytesRead);
        if (read == -1) {
            throw new IOException("End of stream reached before string was fully read");
        }
        bytesRead += read;
    }
    return new String(buffer, StandardCharsets.UTF_8); // Assuming UTF-8 encoding
}

