protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    List<E> edgeList = new ArrayList<>(tour);
    DefaultGraphPath<V, E> graphPath = new DefaultGraphPath<>();

    // Start from an arbitrary vertex of the first edge
    E startEdge = edgeList.get(0);
    V startVertex = graph.getEdgeSource(startEdge);
    graphPath.setStartVertex(startVertex);
    graphPath.setEndVertex(graph.getEdgeTarget(startEdge));
    graphPath.addEdge(startEdge);

    Set<E> visitedEdges = new HashSet<>();
    visitedEdges.add(startEdge);

    V currentVertex = graph.getEdgeTarget(startEdge);

    while (graphPath.getEndVertex() != startVertex || graphPath.getLength() < edgeList.size()) {
        E nextEdge = null;
        for (E edge : graph.edgesOf(currentVertex)) {
            if (!visitedEdges.contains(edge)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("The provided edges do not form a valid tour");
        }

        visitedEdges.add(nextEdge);
        graphPath.addEdge(nextEdge);
        graphPath.setEndVertex(graph.getEdgeTarget(nextEdge));
        currentVertex = graph.getEdgeTarget(nextEdge);
    }

    return graphPath;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, Collections.emptyList(), 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    Map<V, V> predecessorMap = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        predecessorMap.put(target, source);
    }

    V currentVertex = startVertex;
    while (true) {
        V nextVertex = predecessorMap.get(currentVertex);
        if (nextVertex == null) {
            break;
        }
        vertexList.add(nextVertex);
        currentVertex = nextVertex;
    }

    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphWalk<>(graph, startVertex, currentVertex, vertexList, edgeList, weight);
}

