void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Both table and pane must be non-null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index is out of bounds");
    }

    table.getSelectionModel().setSelectionInterval(row, row);
    Rectangle cellRect = table.getCellRect(row, 0, true);
    pane.scrollRectToVisible(cellRect);

    // Delay the repaint to ensure the table has time to properly paint the newly selected row
    table.repaint(cellRect);
    try {
        Thread.sleep(100); // Adjust the sleep time as necessary
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }
    table.repaint();
}

