    path = path.replace(File.separatorChar, '/');
    relativePath = relativePath.replace(File.separatorChar, '/');

    // Tokenize the paths
    String[] pathTokens = path.split("/");
    String[] relativePathTokens = relativePath.split("/");

    // Process the relative path tokens
    int pathIndex = pathTokens.length - 1;
    for (String token : relativePathTokens) {
        if (token.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--; // Move up one directory
            }
        } else if (token.equals(".")) {
            // Stay in the same directory, do nothing
        } else {
            // Add the token as a new directory or file
            pathTokens = Arrays.copyOf(pathTokens, pathTokens.length + 1);
            pathTokens[++pathIndex] = token;
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (result.length() > 0) {
            result.append('/');
        }
        result.append(pathTokens[i]);
    }

    return result.toString();
}

