public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path must not be null");
    }

    // Normalize the path and relative path by removing trailing slashes
    path = path.replaceAll("/+$", "");
    relativePath = relativePath.replaceAll("/+$", "");

    // Use a stack to process the path components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");
    Deque<String> pathStack = new ArrayDeque<>(Arrays.asList(pathComponents));

    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (!pathStack.isEmpty()) {
                pathStack.pop(); // Move up one directory
            }
        } else if (!component.equals(".")) {
            pathStack.push(component); // Add the directory or file
        }
        // If the component is ".", we do nothing as it represents the current directory
    }

    // Reconstruct the path from the stack
    StringBuilder result = new StringBuilder();
    while (!pathStack.isEmpty()) {
        result.insert(0, pathStack.removeLast());
        if (!pathStack.isEmpty()) {
            result.insert(0, "/");
        }
    }

    // If the original path was root or the result is empty, return "/"
    if (result.length() == 0 || (path.equals("/") && relativePath.equals(".."))) {
        return "/";
    }

    return result.toString();
}

